import{_ as t,c as o,o as a,ag as d}from"./chunks/framework.Bw-5EFTY.js";const m=JSON.parse('{"title":"pattern","description":"","frontmatter":{},"headers":[],"relativePath":"docs/rules/pattern.md","filePath":"docs/rules/pattern.md"}'),c={name:"docs/rules/pattern.md"};function l(s,e,p,r,n,i){return a(),o("div",null,e[0]||(e[0]=[d(`<h1 id="pattern" tabindex="-1">pattern <a class="header-anchor" href="#pattern" aria-label="Permalink to &quot;pattern&quot;">​</a></h1><p><code>pattern</code> 是 Whistle 规则中匹配请求 URL 的表达式，支持 URL 片段/域名、通配符、正则表达式等多种匹配方式。</p><h2 id="请求-url-类型" tabindex="-1">请求 URL 类型 <a class="header-anchor" href="#请求-url-类型" aria-label="Permalink to &quot;请求 URL 类型&quot;">​</a></h2><p>Whistle 支持三种请求 URL 类型：</p><table tabindex="0"><thead><tr><th style="text-align:left;">类型</th><th style="text-align:left;">格式</th><th style="text-align:left;">示例</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>隧道代理</strong></td><td style="text-align:left;"><code>tunnel://domain:port</code></td><td style="text-align:left;"><code>tunnel://www.test.com:443</code></td></tr><tr><td style="text-align:left;"><strong>WebSocket</strong></td><td style="text-align:left;"><code>ws[s]://domain[:port]/[path/to[?query]]</code></td><td style="text-align:left;"><code>wss://www.test.com/path?a=1&amp;b=2</code><br><code>ws://www.example.com:8080/path</code></td></tr><tr><td style="text-align:left;"><strong>普通 HTTP/HTTPS</strong></td><td style="text-align:left;"><code>http[s]://domain[:port]/[path/to][?query]</code></td><td style="text-align:left;"><code>https://www.test.com/path</code><br><code>http://www.example.com/path?a=1&amp;b=2</code></td></tr></tbody></table><blockquote><p>URL 中的 hash（即 <code>#</code> 及之后的内容）不会被发送到后台。Hash 仅在客户端（如浏览器）中生效，后台无法直接获取</p></blockquote><h2 id="url" tabindex="-1">URL 片段 <a class="header-anchor" href="#url" aria-label="Permalink to &quot;URL 片段 {#url}&quot;">​</a></h2><p>URL 片段用于匹配请求的 URL，支持多种灵活的模式。以下按匹配规则分类说明。</p><h3 id="_1-域名匹配" tabindex="-1">1. 域名匹配 <a class="header-anchor" href="#_1-域名匹配" aria-label="Permalink to &quot;1. 域名匹配&quot;">​</a></h3><ul><li><p><strong>普通域名</strong>：<code>example.com</code><br> 匹配该域名下所有端口及协议（http/https）的请求。<br> ✅ <code>https://example.com/path/to?query</code><br> ✅ <code>https://example.com:9090/path/to?query</code></p></li><li><p><strong>带端口的域名</strong>：<code>example.com:8080</code><br> 仅匹配指定端口（8080）的请求。<br> ✅ <code>https://example.com:8080/path/to?query</code><br> ❌ <code>https://example.com:9090/path/to?query</code> ❌ <code>https://example.com/path/to?query</code></p></li></ul><h3 id="_2-协议匹配" tabindex="-1">2. 协议匹配 <a class="header-anchor" href="#_2-协议匹配" aria-label="Permalink to &quot;2. 协议匹配&quot;">​</a></h3><ul><li><p><strong>带协议的 URL</strong>：<code>https://example.com/path/to</code><br> 仅匹配相同协议的请求。</p></li><li><p><strong>不带协议的 URL</strong>：<code>example.com/path/to</code> 或 <code>//example.com/path/to</code><br> 匹配任意协议（http、https 等），路径匹配规则与带协议时相同（见下文）。</p></li></ul><h3 id="_3-路径与查询参数匹配" tabindex="-1">3. 路径与查询参数匹配 <a class="header-anchor" href="#_3-路径与查询参数匹配" aria-label="Permalink to &quot;3. 路径与查询参数匹配&quot;">​</a></h3><h4 id="_3-1-不带查询参数的-url" tabindex="-1">3.1 不带查询参数的 URL <a class="header-anchor" href="#_3-1-不带查询参数的-url" aria-label="Permalink to &quot;3.1 不带查询参数的 URL&quot;">​</a></h4><p>模式：<code>https://example.com/path/to</code><br> 匹配规则：<strong>路径前缀匹配</strong>（以 <code>/</code> 为边界）。</p><ul><li>✅ <code>https://example.com/path/to</code></li><li>✅ <code>https://example.com/path/to/xxx?query</code></li><li>❌ <code>https://example.com/path/toxxx</code>（<code>to</code> 后缺少 <code>/</code> 边界）</li></ul><h4 id="_3-2-带查询参数的-url" tabindex="-1">3.2 带查询参数的 URL <a class="header-anchor" href="#_3-2-带查询参数的-url" aria-label="Permalink to &quot;3.2 带查询参数的 URL&quot;">​</a></h4><p>模式：<code>https://example.com/path/to?xxx</code><br> 匹配规则：<strong>路径必须完全相同</strong>，且查询字符串以 <code>xxx</code> 为前缀。</p><ul><li>✅ <code>https://example.com/path/to?xxx</code></li><li>✅ <code>https://example.com/path/to?xxxyyy&amp;zzzzz</code></li><li>❌ <code>https://example.com/path/to/yyy?xxx</code>（路径不同）</li></ul><h3 id="_4-精确匹配" tabindex="-1">4. 精确匹配 <a class="header-anchor" href="#_4-精确匹配" aria-label="Permalink to &quot;4. 精确匹配&quot;">​</a></h3><p>使用 <code>$</code> 前缀，提供更严格的匹配。</p><ul><li><p><code>$https://example.com/path/to</code><br> 匹配<strong>路径精确</strong>（以 <code>/</code> 为边界），查询参数可任意。<br> ✅ <code>https://example.com/path/to</code><br> ✅ <code>https://example.com/path/to?query</code><br> ❌ <code>https://example.com/path/to/xxx</code></p></li><li><p><code>$https://example.com/path/to?query</code><br> 匹配<strong>路径与查询参数均完全一致</strong>。<br> ✅ <code>https://example.com/path/to?query</code><br> ❌ <code>https://example.com/path/to?query=1</code><br> ❌ <code>https://example.com/path/to</code></p></li><li><p>不带协议的精确匹配：<code>$example.com/path/to</code>（效果同上，协议任意）</p></li></ul><h3 id="domain-wildcard" tabindex="-1">5. 域名通配符 <a class="header-anchor" href="#domain-wildcard" aria-label="Permalink to &quot;5. 域名通配符{#domain-wildcard}&quot;">​</a></h3><p>在<code>域名:端口</code>部分使用 <code>*</code> 或 <code>**</code> 进行模糊匹配。</p><ul><li><p><code>*</code>：匹配 0 个或多个非 <code>.</code> 字符（相当于正则 <code>/[^/?.]*/</code>）。<br> 示例：<code>https://*.example.com/path/to</code><br> ✅ <code>https://www.example.com/path/to</code><br> ✅ <code>https://abc.example.com/path/to/xxx?query</code> ❌ <code>https://a.b.example.com/path/to</code></p></li><li><p><code>**</code>：匹配 0 个或多个任意字符（除 <code>/</code> 和 <code>?</code> 外，相当于正则 <code>/[^/?]*/</code>）。<br> 示例：<code>https://**.example.com:8*/path/to</code><br> ✅ <code>https://foo-bar.example.com:8080/path/to</code> ✅ <code>https://a.b.example.com:8888/path/to</code></p></li><li><p><code>***</code> 及以上：不推荐使用。</p></li></ul><blockquote><p>注意：<code>*</code> 也是 URL 路径中的合法字符。若需在路径部分使用通配符，请参阅 <a href="#wildcard">通配符匹配</a>。</p></blockquote><h3 id="要点总结" tabindex="-1">要点总结 <a class="header-anchor" href="#要点总结" aria-label="Permalink to &quot;要点总结&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式示例</th><th>匹配协议</th><th>匹配端口</th><th>路径匹配规则</th><th>查询参数匹配规则</th></tr></thead><tbody><tr><td><code>example.com</code></td><td>任意</td><td>任意</td><td>-</td><td>-</td></tr><tr><td><code>example.com:8080</code></td><td>任意</td><td>8080</td><td>-</td><td>-</td></tr><tr><td><code>https://example.com/path/to</code></td><td>https</td><td>任意</td><td>前缀（<code>/</code>边界）</td><td>任意</td></tr><tr><td><code>https://example.com/path/to?xxx</code></td><td>https</td><td>任意</td><td>精确</td><td>前缀</td></tr><tr><td><code>$https://example.com/path/to</code></td><td>https</td><td>任意</td><td>精确</td><td>任意</td></tr><tr><td><code>$https://example.com/path/to?xxx</code></td><td>https</td><td>任意</td><td>精确</td><td>精确</td></tr><tr><td><code>example.com/path/to</code> <br> 或 <code>//example.com/path/to</code></td><td>任意</td><td>任意</td><td>前缀（<code>/</code>边界）</td><td>任意</td></tr></tbody></table><h2 id="wildcard" tabindex="-1">通配符匹配 <a class="header-anchor" href="#wildcard" aria-label="Permalink to &quot;通配符匹配 {#wildcard}&quot;">​</a></h2><p>在 <a href="#url">URL 片段匹配</a> 中，由于 <code>*</code> 本身是 URL 路径中的合法字符，因此无法直接在路径或查询参数中使用通配符。<br> 若需在 <strong>路径</strong> 或 <strong>查询参数</strong> 中使用通配符，请在 URL 前加上 <code>^</code> 符号。此时 <code>*</code>、<code>**</code>、<code>***</code> 将作为通配符解析。</p><h3 id="_1-域名通配符" tabindex="-1">1. 域名通配符 <a class="header-anchor" href="#_1-域名通配符" aria-label="Permalink to &quot;1. 域名通配符&quot;">​</a></h3><p>语法与 <a href="#domain-wildcard">URL 片段中的域名通配符</a> 完全一致：</p><ul><li><code>*</code>：匹配 0 个或多个非 <code>.</code> 字符（正则 <code>/[^/?.]*/</code>）</li><li><code>**</code>：匹配 0 个或多个任意字符（除 <code>/</code> 和 <code>?</code> 外，正则 <code>/[^/?]*/</code>）</li></ul><p><strong>示例</strong>：<code>^wss://*.example.com/path/to</code></p><p>✅ 匹配：</p><ul><li><code>wss://a.example.com/path/to</code></li><li><code>wss://b.example.com/path/to/xxx?query</code></li></ul><p>❌ 不匹配：</p><ul><li><code>wss://a.example.com/path/toxxx</code>（路径缺少 <code>/</code> 边界）</li><li><code>wss://a.b.example.com/path/to</code>（<code>*</code> 不匹配点号）</li></ul><h3 id="_2-路径通配符" tabindex="-1">2. 路径通配符 <a class="header-anchor" href="#_2-路径通配符" aria-label="Permalink to &quot;2. 路径通配符&quot;">​</a></h3><p>作用于 URL 的 <strong>路径部分</strong>（域名后、<code>?</code> 之前）。支持三种级别：</p><table tabindex="0"><thead><tr><th>通配符</th><th>匹配规则（正则）</th><th>说明</th></tr></thead><tbody><tr><td><code>*</code></td><td><code>/[^?/]*/</code></td><td>匹配当前路径段内的任意字符（不含 <code>/</code> 和 <code>?</code>）</td></tr><tr><td><code>**</code></td><td><code>/[^?]*/</code></td><td>匹配任意字符（不含 <code>?</code>），可跨路径段</td></tr><tr><td><code>***</code></td><td><code>/.*/</code></td><td>匹配剩余所有字符（含 <code>/</code> 和 <code>?</code>），通常用于路径末尾</td></tr></tbody></table><p><strong>示例 1：<code>*</code></strong><br> 模式：<code>^https://example.com/path/to/a*b</code><br> ✅ 匹配：<code>https://example.com/path/to/axxxb/...?query</code><br> ❌ 不匹配：<code>https://example.com/path/to/a/b</code>（<code>*</code> 不能匹配 <code>/</code>）</p><p><strong>示例 2：<code>**</code></strong><br> 模式：<code>^https://example.com/path/to/a**b</code><br> ✅ 匹配：</p><ul><li><code>https://example.com/path/to/axxxb/...?query</code></li><li><code>https://example.com/path/to/a/b</code><br> ❌ 不匹配：<code>https://example.com/path/to/a/xxxx?query=b</code>（<code>?</code> 后不属于路径）</li></ul><p><strong>示例 3：<code>***</code></strong><br> 模式：<code>^https://www.example*.com:8*/path/to/a***b</code><br> ✅ 匹配：</p><ul><li><code>https://example.com/path/to/axxxb/...?query</code></li><li><code>https://example.com/path/to/a/b</code></li><li><code>https://example.com/path/to/a/xxxx?query=b</code>（<code>***</code> 会匹配到 <code>?</code> 及之后）</li></ul><blockquote><p><code>***</code> 会“吞掉”包括 <code>?</code> 在内的剩余字符，一般仅建议在路径末尾使用。</p></blockquote><h3 id="_3-查询参数通配符" tabindex="-1">3. 查询参数通配符 <a class="header-anchor" href="#_3-查询参数通配符" aria-label="Permalink to &quot;3. 查询参数通配符&quot;">​</a></h3><p>作用于 URL 的 <strong>查询字符串</strong>（<code>?</code> 之后）。支持两种：</p><table tabindex="0"><thead><tr><th>通配符</th><th>匹配规则（正则）</th><th>说明</th></tr></thead><tbody><tr><td><code>*</code></td><td><code>/[^&amp;]*/</code></td><td>匹配单个参数值内的任意字符（不含 <code>&amp;</code>）</td></tr><tr><td><code>**</code></td><td><code>/.*/</code></td><td>匹配剩余所有字符（含 <code>&amp;</code>），即从当前位置到末尾</td></tr></tbody></table><p><strong>示例 1：<code>*</code></strong><br> 模式：<code>^https://example.com/path/to?query=a*b</code><br> ✅ 匹配：<code>https://example.com/path/to?query=ab&amp;q2=xxx</code><br> ❌ 不匹配：<code>https://example.com/path/to?query=a&amp;q2=b</code>（<code>b</code> 前无额外字符）</p><p><strong>示例 2：<code>**</code></strong><br> 模式：<code>^https://example.com/path/to?query=a**b</code><br> ✅ 匹配：</p><ul><li><code>https://example.com/path/to?query=axxxb&amp;q2=xxx</code></li><li><code>https://example.com/path/to?query=a&amp;q2=b</code>（<code>**</code> 匹配了 <code>&amp;q2=</code>）</li></ul><h3 id="_4-不带协议的精确匹配" tabindex="-1">4. 不带协议的精确匹配 <a class="header-anchor" href="#_4-不带协议的精确匹配" aria-label="Permalink to &quot;4. 不带协议的精确匹配&quot;">​</a></h3><p>在 <code>^</code> 后直接写域名和路径，协议任意。</p><p><strong>示例</strong>：<code>^example*.com/path*/to</code><br> 效果与带协议相同，但可匹配 <code>http://</code>、<code>https://</code>、<code>wss://</code> 等任意协议。</p><h3 id="_5-精确匹配-边界控制" tabindex="-1">5. 精确匹配（边界控制） <a class="header-anchor" href="#_5-精确匹配-边界控制" aria-label="Permalink to &quot;5. 精确匹配（边界控制）&quot;">​</a></h3><p>在模式末尾使用 <code>$</code>，表示匹配必须到此结束（之后不能再有额外字符）。</p><p><strong>示例</strong>：<code>^https://*.example.com/path/*/to$</code><br> ✅ 匹配：<code>https://a.example.com/path/xxx/to</code><br> ❌ 不匹配：<code>https://b.example.com/path/xxx/to?query</code>（<code>$</code> 禁止 <code>?query</code>）</p><blockquote><p>若不加 <code>$</code>，模式默认允许路径之后继续存在 <code>/</code>、<code>?</code> 等字符。</p></blockquote><h3 id="使用总结" tabindex="-1">使用总结 <a class="header-anchor" href="#使用总结" aria-label="Permalink to &quot;使用总结&quot;">​</a></h3><table tabindex="0"><thead><tr><th>使用场景</th><th>前缀</th><th>通配符类型</th><th>支持的通配符</th><th>示例</th></tr></thead><tbody><tr><td>普通 URL 匹配（无通配符）</td><td>无</td><td>—</td><td>—</td><td><code>https://example.com/path</code></td></tr><tr><td>含通配符的路径/参数</td><td><code>^</code></td><td>域名、路径、查询</td><td><code>*</code> <code>**</code> <code>***</code></td><td><code>^https://*.example.com/path/*?a**b</code></td></tr><tr><td>精确匹配（尾部边界）</td><td><code>^</code> + <code>$</code></td><td>同上</td><td>同上</td><td><code>^https://example.com/path/*/to$</code></td></tr></tbody></table><blockquote><p><strong>注意</strong>：一旦使用 <code>^</code>，URL 中的 <code>*</code> 不再作为普通字符，而是通配符。如需匹配字面意义上的 <code>*</code>，请勿使用 <code>^</code>。</p></blockquote><h2 id="regexp" tabindex="-1">正则匹配 <a class="header-anchor" href="#regexp" aria-label="Permalink to &quot;正则匹配 {#regexp}&quot;">​</a></h2><p>除了前面介绍的 URL 片段匹配和通配符匹配外，Whistle 还提供了完整的正则表达式支持。<br> 正则匹配的语法与 JavaScript 正则表达式完全兼容：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pattern/[i]</span></span></code></pre></div><h3 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h3><ul><li><strong><code>pattern</code></strong>：正则表达式主体</li><li><strong><code>i</code></strong>（可选）：忽略大小写</li></ul><h3 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to &quot;使用示例&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/\\.test\\./              # 匹配字符串中的 &quot;.test.&quot;</span></span>
<span class="line"><span>/key=value/i            # 忽略大小写匹配 &quot;key=value&quot; 或 &quot;KEY=VALUE&quot;</span></span></code></pre></div><h2 id="子匹配传值" tabindex="-1">子匹配传值 <a class="header-anchor" href="#子匹配传值" aria-label="Permalink to &quot;子匹配传值&quot;">​</a></h2><p>在 Whistle 规则中，可以通过 <code>$0</code>、<code>$1</code> … <code>$9</code> 引用通配符或正则表达式捕获的子匹配内容，并将其传递到目标操作值中。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pattern protocol://$0_$1_$2_..._$9</span></span></code></pre></div><p><strong>捕获变量说明</strong>：</p><table tabindex="0"><thead><tr><th>变量</th><th>含义</th></tr></thead><tbody><tr><td><code>$0</code></td><td>完整匹配的内容</td></tr><tr><td><code>$1</code> ~ <code>$9</code></td><td>第 1 至第 9 个捕获组匹配的内容</td></tr></tbody></table><h3 id="通配符匹配传值" tabindex="-1">通配符匹配传值 <a class="header-anchor" href="#通配符匹配传值" aria-label="Permalink to &quot;通配符匹配传值&quot;">​</a></h3><p>使用 <code>^</code> 前缀的通配符模式（<code>*</code>、<code>**</code> 等）会自动按顺序捕获匹配段，分别赋给 <code>$1</code>、<code>$2</code>……。</p><p><strong>示例</strong>：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>^http://*.example.com/v0/users/** file:///User/xxx/$1/$2</span></span></code></pre></div><ul><li>请求 URL：<code>http://www.example.com/v2/users/alice/test.html?q=1</code></li><li>匹配过程： <ul><li><code>$1</code> = <code>www</code>（匹配第一个 <code>*</code>）</li><li><code>$2</code> = <code>users/alice</code>（匹配 <code>**</code> 捕获的路径段）</li></ul></li><li>最终效果：返回本地文件 <code>/User/xxx/www/alice/test.html</code> 的内容</li></ul><blockquote><p>通配符捕获规则：</p><ul><li><code>*</code> 捕获单个路径段（不含 <code>/</code>）</li><li><code>**</code> 捕获剩余路径（可含 <code>/</code>）</li><li>按从左到右顺序依次对应 <code>$1</code>、<code>$2</code>……</li></ul></blockquote><h3 id="正则匹配传值" tabindex="-1">正则匹配传值 <a class="header-anchor" href="#正则匹配传值" aria-label="Permalink to &quot;正则匹配传值&quot;">​</a></h3><p>使用 <code>/pattern/flags</code> 正则表达式时，捕获组 <code>( )</code> 中的内容会按顺序赋给 <code>$1</code>、<code>$2</code>……</p><p><strong>示例</strong>：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/regexp\\/(user|admin)\\/(\\d+)/ reqHeaders://X-Type=$1&amp;X-ID=$2</span></span></code></pre></div><ul><li>请求 URL：<code>.../regexp/admin/123</code></li><li>捕获结果： <ul><li><code>$1</code> = <code>admin</code></li><li><code>$2</code> = <code>123</code></li></ul></li><li>最终效果：为请求添加请求头 <code>X-Type: admin</code> 和 <code>X-ID: 123</code></li></ul><hr><h2 id="路径自动拼接规则" tabindex="-1">路径自动拼接规则 <a class="header-anchor" href="#路径自动拼接规则" aria-label="Permalink to &quot;路径自动拼接规则&quot;">​</a></h2><p>当使用 <strong>域名匹配</strong> 或 <strong>路径匹配</strong> 映射到本地文件/目录或远程 URL 时，Whistle 会自动拼接原请求的剩余路径。</p><p><strong>规则</strong>：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://*.example.com/path/to https://www.test.com/test</span></span>
<span class="line"><span>www.example.com file:///Usr/test</span></span></code></pre></div><p><strong>效果说明</strong>：</p><table tabindex="0"><thead><tr><th>请求 URL</th><th>映射后目标</th></tr></thead><tbody><tr><td><code>https://abc.example.com/path/to/x/y/z?query</code></td><td><code>https://www.test.com/test/x/y/z?query</code></td></tr><tr><td><code>https://www.example.com/path/to/index.html?query</code></td><td>本地文件 <code>/Usr/test/path/to/index.html</code>（自动去除 query）</td></tr></tbody></table><blockquote><p>注意：查询参数 <code>?query</code> 在映射到本地文件时会被自动忽略（文件系统路径不支持），但映射到远程 URL 时会保留。</p></blockquote><hr><h2 id="配置示例" tabindex="-1">配置示例 <a class="header-anchor" href="#配置示例" aria-label="Permalink to &quot;配置示例&quot;">​</a></h2><h3 id="基础匹配" tabindex="-1">基础匹配 <a class="header-anchor" href="#基础匹配" aria-label="Permalink to &quot;基础匹配&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 精确域名匹配</span></span>
<span class="line"><span>api.example.com proxy://127.0.0.1:3000</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 指定端口的域名匹配</span></span>
<span class="line"><span>www.example.com:8080 file:///local/dev</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 路径匹配（映射到本地 JSON 数据）</span></span>
<span class="line"><span>www.example.com/api/users file://{user-data}</span></span></code></pre></div><h3 id="通配符匹配" tabindex="-1">通配符匹配 <a class="header-anchor" href="#通配符匹配" aria-label="Permalink to &quot;通配符匹配&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 匹配所有子域名</span></span>
<span class="line"><span>**.example.com proxy://127.0.0.1:8080</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 匹配特定前缀的子域名</span></span>
<span class="line"><span>dev-**.example.com file:///(dev-mock)</span></span></code></pre></div><h3 id="正则匹配" tabindex="-1">正则匹配 <a class="header-anchor" href="#正则匹配" aria-label="Permalink to &quot;正则匹配&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 匹配数字 ID 的用户页面</span></span>
<span class="line"><span>/^https?://www\\.example\\.com/user/(\\d+)/ file://(user-$1)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 忽略大小写匹配特定路径</span></span>
<span class="line"><span>/\\/api\\/v1\\/data/i resBody://({&quot;version&quot;:&quot;v1&quot;})</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 匹配静态资源文件并设置缓存</span></span>
<span class="line"><span>/\\.(jpg|png|gif|css|js)$/i cache://86400</span></span></code></pre></div><h3 id="复杂匹配" tabindex="-1">复杂匹配 <a class="header-anchor" href="#复杂匹配" aria-label="Permalink to &quot;复杂匹配&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 通配符 + 路径捕获传值</span></span>
<span class="line"><span>^https://**.example.com/api/*/v*/users reqHeaders://x-api-version=$3</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 按请求方法区分处理</span></span>
<span class="line"><span>www.example.com/api file://({&quot;status&quot;:&quot;ok&quot;}) includeFilter://m:GET</span></span>
<span class="line"><span>www.example.com/api file://({&quot;status&quot;:&quot;created&quot;}) includeFilter://m:POST</span></span></code></pre></div><hr><h2 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to &quot;故障排除&quot;">​</a></h2><h3 id="q-规则没有匹配到请求" tabindex="-1">Q：规则没有匹配到请求 <a class="header-anchor" href="#q-规则没有匹配到请求" aria-label="Permalink to &quot;Q：规则没有匹配到请求&quot;">​</a></h3><p><strong>可能原因及解决方案</strong>：</p><ol><li><p><strong>URL 格式不正确</strong><br> → 确保规则中的协议（http/https/ws/wss）与请求一致，或使用不带协议的写法（<code>example.com/path</code>）。</p></li><li><p><strong>端口号不匹配</strong><br> → 如果请求使用非标准端口，需要在规则中明确指定端口（如 <code>example.com:8080</code>）。</p></li><li><p><strong>通配符或正则表达式有误</strong><br> → 使用 <a href="https://github.com/avwo/whistle" target="_blank" rel="noreferrer">Whistle 在线调试工具</a> 或本地日志验证匹配情况。</p></li><li><p><strong>规则优先级问题</strong><br> → 更具体的规则应写在前面，或使用 <code>$</code> 精确匹配提高优先级。</p></li></ol><h3 id="q-正则表达式不生效" tabindex="-1">Q：正则表达式不生效 <a class="header-anchor" href="#q-正则表达式不生效" aria-label="Permalink to &quot;Q：正则表达式不生效&quot;">​</a></h3><p><strong>检查清单</strong>：</p><ul><li>[ ] 正则表达式是否以 <code>/</code> 开头和结尾，如 <code>/pattern/</code>？</li><li>[ ] 特殊字符是否已转义（如 <code>.</code> 需写成 <code>\\.</code>，<code>/</code> 需写成 <code>\\/</code>）？</li><li>[ ] 标志（<code>i</code> 等）是否正确添加？</li><li>[ ] 正则是否匹配完整的 URL？可以在控制台用 <code>new RegExp(&#39;pattern&#39;, &#39;flags&#39;).test(url)</code> 验证。</li></ul><h3 id="q-子匹配传值不正确" tabindex="-1">Q：子匹配传值不正确 <a class="header-anchor" href="#q-子匹配传值不正确" aria-label="Permalink to &quot;Q：子匹配传值不正确&quot;">​</a></h3><p><strong>常见问题</strong>：</p><ol><li><p><strong>捕获组编号错误</strong><br> → <code>$1</code> 对应第一个 <code>( )</code>，<code>$2</code> 对应第二个，依次类推。注意嵌套捕获组的顺序。</p></li><li><p><strong>通配符捕获不符合预期</strong><br> → <code>*</code> 不匹配点号（<code>.</code>）和斜杠（<code>/</code>），<code>**</code> 匹配任意字符（除 <code>?</code> 外）。<br> → 示例：<code>*.example.com</code> 无法匹配 <code>a.b.example.com</code>，需改用 <code>**.example.com</code>。</p></li><li><p><strong>正则捕获组未按预期工作</strong><br> → 使用 <code>(?:)</code> 表示非捕获组，避免干扰编号。<br> → 使用在线正则测试工具（如 regex101.com）验证捕获内容。</p></li></ol><h3 id="q-映射到本地文件时路径错误" tabindex="-1">Q：映射到本地文件时路径错误 <a class="header-anchor" href="#q-映射到本地文件时路径错误" aria-label="Permalink to &quot;Q：映射到本地文件时路径错误&quot;">​</a></h3><ul><li>使用 <code>file://</code> 协议时，确保路径是绝对路径（如 <code>file:///User/xxx</code>）。</li><li>路径拼接遵循自动拼接规则，请求的剩余路径会追加到目标路径后。</li><li>查询参数会被自动忽略，不影响文件读取。</li></ul><hr><h2 id="扩展阅读" tabindex="-1">扩展阅读 <a class="header-anchor" href="#扩展阅读" aria-label="Permalink to &quot;扩展阅读&quot;">​</a></h2><ul><li><a href="./rule.html">规则语法文档</a>：了解完整的规则语法结构</li><li><a href="./operation.html">操作指令文档</a>：学习如何配置操作指令</li><li><a href="./filters.html">过滤器文档</a>：了解如何精确控制规则生效条件</li></ul>`,120)]))}const x=t(c,[["render",l]]);export{m as __pageData,x as default};
